<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Foundry\SubordinatePersonaSpecificationService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:foundry:specify-subordinate-persona',description:'Have the Artificer seal one bounded Persona specification for an exact subordinate construction case')]
final class FoundrySpecifySubordinatePersonaCommand extends Command{public function __construct(private readonly SubordinatePersonaSpecificationService $service){parent::__construct();}protected function configure():void{$this->addArgument('case-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->service->specify((string)$i->getArgument('case-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}if((bool)$i->getOption('json')){$o->writeln(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));return self::SUCCESS;}$o->writeln('<info>SUBORDINATE_PERSONA_SPECIFICATION_SEALED</info> '.$r['specification_id']);$o->writeln('Case: '.$r['case_id']);$o->writeln('Persona: '.$r['specification']['persona_name']);$o->writeln('Status: '.$r['status']);$o->writeln('Persona selection authority: NOT GRANTED');$o->writeln('Profile approval authority: NOT GRANTED');$o->writeln('Spawning authority: NOT GRANTED');$o->writeln('Admission authority: NOT GRANTED');$o->writeln('Execution authority: NOT GRANTED');return self::SUCCESS;}}
